message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action modifies an implementation artifact in an attempt to resolve a failure identified by an earlier execution observation.",
      "source_description": "An execution observation reporting a failure or incorrect behavior of a produced artifact.",
      "target_description": "A subsequent agent action that modifies the implementation to address that failure."
    },
    {
      "name": "VERIFIES_REPAIR",
      "definition": "After modifying an implementation to fix a failure, the agent re-executes test(s) to determine whether the modification actually resolved the failure.",
      "source_description": "An agent action that modified an implementation to correct an earlier failure.",
      "target_description": "A subsequent test execution that checks whether the prior failure has been resolved."
    },
    {
      "name": "VERIFICATION_SUCCESS_TRIGGERS_COMPLETION",
      "definition": "A successful verification result that satisfies the task requirements leads the agent to declare the task complete.",
      "source_description": "An execution result indicating that verification of the task requirements succeeded.",
      "target_description": "An agent action signaling that the task is complete."
    },
    {
      "name": "EXTENDS_VERIFICATION_FOR_IDENTIFIED_RISK",
      "definition": "An identified untested edge case or potential failure mode prompts the agent to construct and run an additional verification specifically targeting that scenario.",
      "source_description": "An identified gap, edge case, or potential failure mode not yet covered by existing verification.",
      "target_description": "A newly constructed verification action designed to exercise that previously uncovered scenario."
    },
    {
      "name": "USES_PRODUCED_ARTIFACT",
      "definition": "A subsequent action consumes or depends on an artifact produced by an earlier agent action, using it as an input or dependency.",
      "source_description": "An artifact produced by an earlier agent action.",
      "target_description": "A subsequent agent action that uses the produced artifact as an input or dependency."
    },
    {
      "name": "INSPECTS_ARTIFACT_TO_CONFIRM_CONTENT",
      "definition": "The agent retrieves the content of a previously produced artifact in order to confirm that it matches the expected final state before concluding.",
      "source_description": "A previously produced artifact whose final content is to be confirmed.",
      "target_description": "An agent action that reads the artifact to verify its content."
    }
  ]
}

